/* CSS PART 1 OF 4 */

/* ==========================================================
   JOSH BROOKS CONSTRUCTION & RENOVATION INC.
   Design direction: Modern craftsmanship / Colorado residential
   Palette: Deep graphite, warm limestone, muted copper
   ========================================================== */

/* 1. DESIGN TOKENS
   ---------------------------------------------------------- */

:root {
  color-scheme: light;

  /* Brand-inspired colors */
  --color-ink: #202a30;
  --color-ink-soft: #35434a;
  --color-slate: #647078;
  --color-stone: #e9e5dc;
  --color-limestone: #f5f3ee;
  --color-paper: #fcfbf8;
  --color-white: #ffffff;

  /* Accent */
  --color-accent: #bd7849;
  --color-accent-dark: #965b35;
  --color-accent-light: #ead5c2;

  /* Utility colors */
  --color-border: #dedbd3;
  --color-muted: #858b8c;
  --color-success: #52715d;
  --color-focus: #d18a4e;

  /* Typography */
  --font-heading: "DM Sans", "Arial", sans-serif;
  --font-body: "Inter", "Helvetica Neue", sans-serif;

  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-md: 1.125rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: clamp(1.75rem, 3vw, 2.5rem);
  --font-size-3xl: clamp(2.25rem, 4.5vw, 3.5rem);
  --font-size-display: clamp(2.75rem, 6vw, 5.25rem);

  --line-height-tight: 1.08;
  --line-height-heading: 1.2;
  --line-height-body: 1.7;

  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-extrabold: 800;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --container-width: 1240px;
  --container-narrow: 860px;
  --container-padding: clamp(1.25rem, 5vw, 4rem);
  --section-spacing: clamp(4rem, 8vw, 7.5rem);

  /* Borders and shapes */
  --border-thin: 1px solid var(--color-border);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 14px;
  --radius-pill: 999px;

  /* Shadows */
  --shadow-subtle: 0 4px 18px rgba(32, 42, 48, 0.06);
  --shadow-medium: 0 12px 36px rgba(32, 42, 48, 0.12);
  --shadow-strong: 0 20px 60px rgba(20, 29, 34, 0.18);

  /* Transitions */
  --transition-fast: 180ms ease;
  --transition-normal: 280ms ease;

  /* Navigation */
  --header-height: 84px;
}


/* 2. RESET AND DOCUMENT FOUNDATIONS
   ---------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-height) + 1rem);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-regular);
  line-height: var(--line-height-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-wrap: break-word;
}

img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
select {
  cursor: pointer;
}

button {
  color: inherit;
}

a {
  color: inherit;
  text-decoration: none;
  text-underline-offset: 4px;
}

a:hover {
  color: var(--color-accent-dark);
}

ul,
ol {
  padding-left: 1.4rem;
}

p,
h1,
h2,
h3,
h4,
h5,
h6,
figure {
  margin-top: 0;
}

p:last-child {
  margin-bottom: 0;
}

::selection {
  color: var(--color-white);
  background: var(--color-ink);
}


/* 3. ACCESSIBILITY FOUNDATIONS
   ---------------------------------------------------------- */

:focus {
  outline: none;
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: 9999;
  top: 0;
  left: 1rem;
  padding: 0.75rem 1.25rem;
  background: var(--color-ink);
  color: var(--color-white);
  font-weight: var(--font-weight-semibold);
  transform: translateY(-150%);
  transition: transform var(--transition-fast);
}

.skip-link:focus {
  color: var(--color-white);
  transform: translateY(0);
}

[hidden] {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}


/* 4. TYPOGRAPHY SYSTEM
   ---------------------------------------------------------- */

h1,
h2,
h3,
h4,
h5,
h6 {
  margin-bottom: var(--space-5);
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.045em;
  line-height: var(--line-height-heading);
}

h1 {
  font-size: var(--font-size-display);
  font-weight: var(--font-weight-extrabold);
  line-height: var(--line-height-tight);
  letter-spacing: -0.055em;
}

h2 {
  font-size: var(--font-size-3xl);
}

h3 {
  font-size: var(--font-size-xl);
  letter-spacing: -0.025em;
}

h4 {
  font-size: var(--font-size-lg);
  letter-spacing: -0.02em;
}

p {
  margin-bottom: var(--space-5);
  color: var(--color-slate);
  line-height: var(--line-height-body);
}

strong,
b {
  color: var(--color-ink);
  font-weight: var(--font-weight-semibold);
}

small {
  font-size: var(--font-size-sm);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-5);
  color: var(--color-accent-dark);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.16em;
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: var(--color-accent);
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: var(--space-6);
}

.section-intro {
  max-width: 680px;
  font-size: var(--font-size-md);
}

.text-light {
  color: var(--color-white);
}

.text-muted {
  color: var(--color-muted);
}

.text-accent {
  color: var(--color-accent-dark);
}


/* 5. PAGE GRID AND CONTAINER SYSTEM
   ---------------------------------------------------------- */

.site-wrapper {
  width: 100%;
  min-height: 100vh;
  overflow: clip;
}

.container {
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
}

.container--narrow {
  max-width: var(--container-narrow);
}

.container--wide {
  width: min(94%, 1440px);
  margin-inline: auto;
}

.section {
  position: relative;
  padding-block: var(--section-spacing);
}

.section--compact {
  padding-block: clamp(3rem, 5vw, 4.5rem);
}

.section--light {
  background: var(--color-paper);
}

.section--stone {
  background: var(--color-limestone);
}

.section--dark {
  background: var(--color-ink);
  color: var(--color-white);
}

.section--dark h2,
.section--dark h3,
.section--dark h4,
.section--dark strong {
  color: var(--color-white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.72);
}


/* 6. SHARED LAYOUT PRIMITIVES
   ---------------------------------------------------------- */

.grid {
  display: grid;
  gap: var(--space-8);
}

.grid--2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid--3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid--4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.flex {
  display: flex;
}

.flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

.flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.align-center {
  align-items: center;
}

.align-start {
  align-items: flex-start;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}

.flow-content > * + * {
  margin-top: var(--space-5);
}

.split-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: center;
  gap: clamp(2.5rem, 6vw, 6rem);
}

.split-layout--reverse > :first-child {
  order: 2;
}

.split-layout--reverse > :last-child {
  order: 1;
}

.content-width {
  max-width: 720px;
}

.centered {
  margin-inline: auto;
  text-align: center;
}


/* 7. IMAGE AND MEDIA FOUNDATIONS
   ---------------------------------------------------------- */

.image-frame {
  position: relative;
  overflow: hidden;
  background: var(--color-stone);
  border-radius: var(--radius-md);
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-frame--landscape {
  aspect-ratio: 4 / 3;
}

.image-frame--portrait {
  aspect-ratio: 3 / 4;
}

.image-frame--wide {
  aspect-ratio: 16 / 9;
}

.image-frame--square {
  aspect-ratio: 1;
}

.image-cover {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.media-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(20, 29, 34, 0.02) 25%,
    rgba(20, 29, 34, 0.68) 100%
  );
}


/* 8. RESPONSIVE BREAKPOINT FOUNDATIONS
   ---------------------------------------------------------- */

@media (max-width: 1024px) {
  :root {
    --header-height: 76px;
    --section-spacing: clamp(3.75rem, 7vw, 5.5rem);
  }

  .grid--4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .split-layout {
    gap: var(--space-10);
  }
}

@media (max-width: 768px) {
  :root {
    --header-height: 70px;
    --container-padding: 1.25rem;
    --section-spacing: 4rem;
  }

  h1 {
    font-size: clamp(2.6rem, 10vw, 4rem);
  }

  h2 {
    font-size: clamp(2rem, 7vw, 2.75rem);
  }

  .grid--2,
  .grid--3,
  .grid--4,
  .split-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .split-layout--reverse > :first-child,
  .split-layout--reverse > :last-child {
    order: initial;
  }

  .section-heading {
    margin-bottom: var(--space-5);
  }

  .section-intro {
    font-size: var(--font-size-base);
  }
}

@media (max-width: 480px) {
  :root {
    --container-padding: 1rem;
    --section-spacing: 3.5rem;
  }

  h1 {
    font-size: clamp(2.35rem, 11vw, 3.25rem);
  }

  h2 {
    font-size: 2rem;
  }

  .grid {
    gap: var(--space-6);
  }

  .eyebrow {
    font-size: 0.7rem;
  }
}
