/* CSS PART 2 OF 4 */

/* ==========================================================
   HEADER, NAVIGATION, HERO & PRIMARY CONVERSION ACTIONS
   Josh Brooks Construction and Renovation Inc.
   ========================================================== */


/* 1. SITE HEADER
   ---------------------------------------------------------- */

.site-header {
  position: sticky;
  z-index: 1000;
  top: 0;
  width: 100%;
  min-height: var(--header-height);
  background: rgba(252, 251, 248, 0.97);
  border-bottom: 1px solid rgba(32, 42, 48, 0.09);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8);
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-width)
  );
  min-height: var(--header-height);
  margin-inline: auto;
}

.site-brand {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: var(--space-3);
  max-width: 270px;
  color: var(--color-ink);
  text-decoration: none;
}

.site-brand:hover {
  color: var(--color-ink);
}

.site-brand img {
  display: block;
  width: auto;
  max-width: 72px;
  max-height: 58px;
  object-fit: contain;
}

.site-brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.site-brand-name {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: var(--font-weight-extrabold);
  letter-spacing: -0.035em;
  line-height: 1.2;
}

.site-brand-description {
  color: var(--color-slate);
  font-size: 0.62rem;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.11em;
  line-height: 1.3;
  text-transform: uppercase;
}


/* 2. PRIMARY NAVIGATION
   ---------------------------------------------------------- */

.primary-navigation {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(1rem, 2vw, 2rem);
}

.primary-navigation ul {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 2vw, 1.75rem);
  margin: 0;
  padding: 0;
  list-style: none;
}

.primary-navigation li {
  margin: 0;
  padding: 0;
}

.primary-navigation a:not(.button) {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--color-ink-soft);
  font-size: 0.82rem;
  font-weight: var(--font-weight-semibold);
  text-decoration: none;
  transition: color var(--transition-fast);
}

.primary-navigation a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 2px;
  background: var(--color-accent);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition-normal);
}

.primary-navigation a:not(.button):hover {
  color: var(--color-accent-dark);
}

.primary-navigation a:not(.button):hover::after,
.primary-navigation a[aria-current="page"]::after {
  transform: scaleX(1);
}

.primary-navigation a[aria-current="page"] {
  color: var(--color-ink);
}

.header-actions {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  gap: var(--space-3);
}


/* 3. BUTTON SYSTEM
   ---------------------------------------------------------- */

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  padding: 0.85rem 1.6rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-family: var(--font-heading);
  font-size: 0.88rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.005em;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast),
    box-shadow var(--transition-fast),
    transform var(--transition-fast);
  cursor: pointer;
}

.button:hover {
  text-decoration: none;
  transform: translateY(-2px);
}

.button:active {
  transform: translateY(0);
}

.button--primary {
  background: var(--color-accent);
  color: var(--color-white);
  box-shadow: 0 5px 14px rgba(189, 120, 73, 0.17);
}

.button--primary:hover {
  background: var(--color-accent-dark);
  color: var(--color-white);
  box-shadow: 0 8px 20px rgba(150, 91, 53, 0.22);
}

.button--dark {
  background: var(--color-ink);
  color: var(--color-white);
}

.button--dark:hover {
  background: var(--color-ink-soft);
  color: var(--color-white);
}

.button--outline {
  border-color: rgba(32, 42, 48, 0.28);
  background: transparent;
  color: var(--color-ink);
}

.button--outline:hover {
  border-color: var(--color-ink);
  background: var(--color-ink);
  color: var(--color-white);
}

.button--light {
  background: var(--color-white);
  color: var(--color-ink);
}

.button--light:hover {
  background: var(--color-limestone);
  color: var(--color-ink);
}

.button--full {
  width: 100%;
}

.button--small {
  min-height: 44px;
  padding: 0.7rem 1.1rem;
  font-size: 0.8rem;
}


/* 4. CONTACT DETAILS IN HEADER
   ---------------------------------------------------------- */

.header-phone {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.header-phone-label {
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.header-phone a {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: var(--font-weight-bold);
  white-space: nowrap;
}

.header-phone a:hover {
  color: var(--color-accent-dark);
}


/* 5. MOBILE NAVIGATION CONTROLS
   ---------------------------------------------------------- */

.menu-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  padding: 0;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-paper);
  color: var(--color-ink);
}

.menu-toggle:hover {
  border-color: var(--color-accent);
  background: var(--color-limestone);
}

.menu-toggle span {
  position: relative;
  display: block;
  width: 21px;
  height: 2px;
  background: currentColor;
  transition: background var(--transition-fast);
}

.menu-toggle span::before,
.menu-toggle span::after {
  position: absolute;
  left: 0;
  width: 21px;
  height: 2px;
  background: currentColor;
  content: "";
  transition:
    transform var(--transition-fast),
    top var(--transition-fast);
}

.menu-toggle span::before {
  top: -7px;
}

.menu-toggle span::after {
  top: 7px;
}

.menu-toggle[aria-expanded="true"] span {
  background: transparent;
}

.menu-toggle[aria-expanded="true"] span::before {
  top: 0;
  transform: rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span::after {
  top: 0;
  transform: rotate(-45deg);
}


/* 6. HERO SECTION
   ---------------------------------------------------------- */

.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: min(760px, calc(100svh - var(--header-height)));
  padding-block: clamp(4.5rem, 9vw, 8rem);
  overflow: hidden;
  background: var(--color-ink);
  color: var(--color-white);
}

.hero::before {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(22, 31, 36, 0.94) 0%,
      rgba(22, 31, 36, 0.83) 40%,
      rgba(22, 31, 36, 0.28) 100%
    );
  content: "";
  pointer-events: none;
}

.hero-background {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-background img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(260px, 0.65fr);
  align-items: center;
  gap: clamp(2rem, 7vw, 7rem);
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
}

.hero-content {
  max-width: 760px;
}

.hero .eyebrow {
  color: #e6b68f;
}

.hero .eyebrow::before {
  background: #e6b68f;
}

.hero h1 {
  max-width: 760px;
  margin-bottom: var(--space-6);
  color: var(--color-white);
}

.hero h1 em {
  color: #e8b78e;
  font-style: normal;
}

.hero-description {
  max-width: 580px;
  margin-bottom: var(--space-8);
  color: rgba(255, 255, 255, 0.83);
  font-size: clamp(1.05rem, 1.7vw, 1.2rem);
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.hero-actions .button {
  min-width: 175px;
  min-height: 58px;
}

.hero-secondary-link {
  display: inline-flex;
  align-items: center;
  min-height: 48px;
  color: var(--color-white);
  font-size: 0.9rem;
  font-weight: var(--font-weight-semibold);
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.45);
  text-underline-offset: 5px;
}

.hero-secondary-link:hover {
  color: #e8b78e;
  text-decoration-color: currentColor;
}


/* 7. HERO TRUST PANEL
   ---------------------------------------------------------- */

.hero-aside {
  align-self: end;
  justify-self: end;
  width: 100%;
  max-width: 340px;
  padding: clamp(1.5rem, 3vw, 2rem);
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-top: 3px solid var(--color-accent);
  background: rgba(24, 34, 39, 0.78);
  box-shadow: var(--shadow-strong);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.hero-aside-label {
  display: block;
  margin-bottom: var(--space-4);
  color: #e8b78e;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.hero-aside h2 {
  margin-bottom: var(--space-3);
  color: var(--color-white);
  font-size: 1.55rem;
}

.hero-aside p {
  margin-bottom: var(--space-5);
  color: rgba(255, 255, 255, 0.75);
  font-size: 0.9rem;
}

.hero-aside .button {
  width: 100%;
}

.hero-credentials {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-top: var(--space-6);
  padding-top: var(--space-5);
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.hero-credential {
  flex: 1 1 120px;
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.7rem;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.045em;
  line-height: 1.5;
  text-transform: uppercase;
}


/* 8. HERO BRAND AND SERVICE STRIP
   ---------------------------------------------------------- */

.hero-bottom {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-width)
  );
  margin: auto auto 0;
  padding-top: var(--space-8);
}

.hero-bottom-label {
  color: rgba(255, 255, 255, 0.64);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.hero-bottom-services {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--space-5);
  margin: 0;
  padding: 0;
  list-style: none;
}

.hero-bottom-services li {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.78rem;
  font-weight: var(--font-weight-medium);
}


/* 9. COMPACT CONTACT ACTION BAR
   ---------------------------------------------------------- */

.contact-action-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  padding: var(--space-5) 0;
  border-bottom: var(--border-thin);
  background: var(--color-paper);
}

.contact-action-bar p {
  margin: 0;
  color: var(--color-ink);
  font-size: 0.9rem;
  font-weight: var(--font-weight-semibold);
}

.contact-action-links {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-5);
}

.contact-action-links a {
  color: var(--color-ink);
  font-size: 0.85rem;
  font-weight: var(--font-weight-bold);
}

.contact-action-links a:hover {
  color: var(--color-accent-dark);
}


/* 10. RESPONSIVE HEADER AND NAVIGATION
   ---------------------------------------------------------- */

@media (max-width: 1100px) {
  .header-inner {
    gap: var(--space-4);
  }

  .primary-navigation {
    gap: var(--space-4);
  }

  .primary-navigation ul {
    gap: var(--space-4);
  }

  .primary-navigation a:not(.button) {
    font-size: 0.76rem;
  }

  .header-phone {
    display: none;
  }
}

@media (max-width: 900px) {
  .menu-toggle {
    display: inline-flex;
    flex: 0 0 auto;
  }

  .primary-navigation {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    align-items: stretch;
    flex-direction: column;
    gap: var(--space-4);
    padding: var(--space-5) var(--container-padding) var(--space-6);
    border-bottom: 1px solid var(--color-border);
    background: var(--color-paper);
    box-shadow: var(--shadow-medium);
  }

  .primary-navigation.is-open {
    display: flex;
  }

  .primary-navigation ul {
    align-items: stretch;
    flex-direction: column;
    gap: 0;
  }

  .primary-navigation li {
    border-bottom: 1px solid var(--color-border);
  }

  .primary-navigation a:not(.button) {
    width: 100%;
    min-height: 48px;
    font-size: 0.95rem;
  }

  .primary-navigation a:not(.button)::after {
    display: none;
  }

  .primary-navigation .button {
    width: 100%;
  }

  .header-actions {
    margin-left: auto;
  }

  .hero-inner {
    grid-template-columns: minmax(0, 1fr);
  }

  .hero-aside {
    justify-self: start;
    max-width: 460px;
  }
}

@media (max-width: 768px) {
  .hero {
    min-height: auto;
    padding-block: 5rem 4rem;
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(22, 31, 36, 0.91),
      rgba(22, 31, 36, 0.68)
    );
  }

  .hero-background img {
    object-position: 58% center;
  }

  .hero-inner {
    gap: var(--space-8);
  }

  .hero h1 {
    max-width: 650px;
  }

  .hero-aside {
    max-width: 100%;
  }

  .hero-bottom {
    align-items: flex-start;
    flex-direction: column;
  }

  .hero-bottom-services {
    justify-content: flex-start;
  }

  .contact-action-bar {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .site-brand {
    gap: var(--space-2);
    max-width: 220px;
  }

  .site-brand img {
    max-width: 48px;
    max-height: 46px;
  }

  .site-brand-name {
    font-size: 0.8rem;
  }

  .site-brand-description {
    font-size: 0.55rem;
  }

  .header-inner {
    gap: var(--space-2);
  }

  .header-actions .button {
    min-height: 43px;
    padding: 0.65rem 0.85rem;
    font-size: 0.72rem;
  }

  .menu-toggle {
    width: 42px;
    height: 42px;
  }

  .hero {
    padding-block: 4rem 3rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-secondary-link {
    justify-content: center;
  }

  .hero-aside {
    padding: var(--space-5);
  }

  .hero-bottom-services {
    gap: var(--space-3);
  }

  .contact-action-links {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-3);
  }
}
